// spec: specs/addbusiness-photos-step.md (1.1–1.3) · кейсы: .qa/tests/addbusiness-photos-step/ADDBIZ-PHOTOS-01..03.md
// seed: tests/seed.user.spec.ts · ПРОД: переход 1→2 создаёт черновик «QA-TEST …» — удаляется в afterEach.
// Запуск только с QA_REAL_WRITE=1. «צור תמונה» не нажимается (генерация не нужна).
// Заменяет прежний no-generic-images-block.spec.ts (#c18c9e: «AI-блока нет» — отменено #def18b).
import { test, expect, Page } from '@playwright/test';
import {
  AI_TITLE, REAL_WRITE, REMOVED, SKIP_REASON, STYLES, Ctl, deleteDraft, goToPhotosStep, interceptDraft, styleCard,
} from './photos-step.helpers';

test.use({ storageState: '../auth/user.json', serviceWorkers: 'block' });
test.describe.configure({ mode: 'serial' });

async function expectAiBlockLastAndNoTemplates(page: Page, isMobile: boolean) {
  // Фото на месте (F-10 AC 02)
  await expect(page.getByText(/\(0\/10\)/)).toBeVisible();
  await expect(page.getByText('JPG, PNG עד 5MB לכל תמונה')).toBeVisible();

  // Шаблонов нет — ни в тексте, ни в HTML («מה רצוי» #def18b; #c18c9e)
  const html = await page.content();
  for (const s of REMOVED) {
    await expect(page.getByText(s), `видимого «${s}» нет`).toHaveCount(0);
    expect(html.includes(s), `«${s}» нет в HTML`).toBe(false);
  }

  // AI-блок: 3 стиля, у каждого «צור תמונה» («מה רצוי» #def18b, комментарий программиста)
  const aiTitle = page.getByText(AI_TITLE, { exact: true });
  await expect(aiTitle).toBeVisible();
  for (const style of STYLES) {
    const card = styleCard(page, style);
    await expect(card, `стиль «${style}»`).toBeVisible();
    await expect(card.getByRole('button', { name: 'צור תמונה' }), `«צור תמונה» у «${style}»`).toBeVisible();
  }
  await expect(page.getByRole('button', { name: 'צור תמונה' })).toHaveCount(3);

  // Порядок сверху вниз (#537c4e: AI-блок в самом низу; реджект #def18b)
  const order = [
    page.getByRole('heading', { name: 'הוסף תמונות לעסק', exact: true }),
    page.getByRole('heading', { name: 'טיפים לתמונות איכותיות:', exact: true }),
    page.getByRole('heading', { name: 'העלאת וידאו (אופציונלי)', exact: true }),
    aiTitle,
  ];
  let prevY = -1;
  for (const el of order) {
    const box = await el.boundingBox();
    expect(box, 'раздел шага виден').not.toBeNull();
    expect(box!.y, 'порядок: фото → советы → видео → AI').toBeGreaterThan(prevY);
    prevY = box!.y;
  }

  // Между AI-блоком и кнопками ничего нет: низ AI-блока = низ последней «צור תמונה»; заголовков между ними нет
  let aiBottom = 0;
  for (const b of await page.getByRole('button', { name: 'צור תמונה' }).all()) {
    const box = (await b.boundingBox())!;
    aiBottom = Math.max(aiBottom, box.y + box.height);
  }
  const next = (await page.getByRole('button', { name: 'שלב הבא' }).boundingBox())!;
  const back = (await page.getByRole('button', { name: 'חזרה', exact: true }).boundingBox())!;
  const navTop = Math.min(next.y, back.y);
  expect(navTop, 'кнопки «חזרה»/«שלב הבא» под AI-блоком').toBeGreaterThanOrEqual(aiBottom);
  for (const h of await page.getByRole('heading').all()) {
    const box = await h.boundingBox();
    if (!box) continue;
    const between = box.y > aiBottom && box.y + box.height < navTop;
    expect(between, `между AI-блоком и кнопками нет раздела «${await h.innerText()}»`).toBe(false);
  }
  if (isMobile) expect(next.y, 'мобайл: «שלב הבא» над «חזרה»').toBeLessThan(back.y);
}

test.describe('Публикация бизнеса — шаг фото: AI-блок внизу, без «טמפלייטים שמורים»', () => {
  let ctl: Ctl | null = null;

  test.beforeEach(() => test.skip(!REAL_WRITE, SKIP_REASON));
  test.afterEach(async ({ page }) => {
    if (ctl) await deleteDraft(page, ctl);
    ctl = null;
  });

  test('Десктоп — AI-блок с 3 стилями внизу шага, шаблонов нет #def18b @desktop @data', async ({ page }) => {
    ctl = await interceptDraft(page, 'def18b');
    await goToPhotosStep(page, ctl, 'בתי קפה ומסעדות');
    await expectAiBlockLastAndNoTemplates(page, false);
    expect(ctl.generateCalls, 'генерации не было').toEqual([]);
    expect(ctl.unexpected, 'кроме своего черновика на прод ничего не записано').toEqual([]);
  });

  test('Категория с шаблонами «כללי» — шаблонов нет, AI-блок есть #def18b @desktop @data', async ({ page }) => {
    ctl = await interceptDraft(page, 'def18b');
    await goToPhotosStep(page, ctl, 'כללי');
    await expectAiBlockLastAndNoTemplates(page, false);
    expect(ctl.generateCalls, 'генерации не было').toEqual([]);
    expect(ctl.unexpected, 'кроме своего черновика на прод ничего не записано').toEqual([]);
  });

  test('Телефон, «פיצוציה/קיוסק» — AI-блок над кнопками, «שלב הבא» над «חזרה», шаблонов нет #def18b @android @data', async ({ page }) => {
    ctl = await interceptDraft(page, 'def18b');
    await goToPhotosStep(page, ctl, 'פיצוציה/קיוסק');
    await expectAiBlockLastAndNoTemplates(page, true);
    expect(ctl.generateCalls, 'генерации не было').toEqual([]);
    expect(ctl.unexpected, 'кроме своего черновика на прод ничего не записано').toEqual([]);
  });
});
